'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=['Financial Aid','Registrar','Bursar'], icons=['♧','▤','▣'], navs=[['student','◈','Student portal'],['advisor','▤','Advisor workspace'],['supervisor','▥','Supervisor hub'],['admin','⚙','Administration'],['analytics','↗','Service analytics']];
const initial=()=>({departments:names.map((name,i)=>({name,hours:'9:00 AM – 5:00 PM',open:true,minutes:[12,8,10][i]})),staff:[{id:'a1',name:'Morgan Ellis',role:'Advisor',dept:'Financial Aid',active:true},{id:'a2',name:'Jordan Brooks',role:'Advisor',dept:'Financial Aid',active:true},{id:'a3',name:'Taylor Reed',role:'Advisor',dept:'Registrar',active:true},{id:'a4',name:'Cameron Scott',role:'Advisor',dept:'Bursar',active:true},{id:'a5',name:'Avery James',role:'Advisor',dept:'Bursar',active:false}],tickets:Array.from({length:11},(_,i)=>({id:'HH-'+(1041+i),studentId:'@03'+(196540+i),name:['Alex Johnson','Riley Williams','Sam Davis','Jamie Thomas','Drew Wilson','Casey Robinson','Parker Lee','Skyler Harris','Quinn Clark','Emerson Lewis','Sage Walker'][i],dept:names[i%3],category:['Aid disbursement','Course registration','Account hold'][i%3],summary:['My financial aid has not been applied to my account.','I need help updating my course registration.','I need to understand and resolve my account hold.'][i%3],contact:'student'+(i+1)+'@example.edu',urgency:i===3?'High':'Normal',status:'Waiting',created:Date.now()-(12+i*3)*60000,repeat:i%4===0})),cases:[{id:'CASE-2026-0108',studentId:'@03196540',name:'Alex Johnson',advisor:'Morgan Ellis',dept:'Financial Aid',summary:'Reviewed aid eligibility and verified the outstanding verification document.',pending:'Upload the signed verification form through your student portal.',status:'In Progress',created:Date.now()-86400000}],routing:{'Aid disbursement':'Financial Aid','Scholarships':'Financial Aid','Course registration':'Registrar','Enrollment verification':'Registrar','Account hold':'Bursar','Payment plan':'Bursar'},notifications:[],own:null,health:true,requests:[],history:[{label:'Week 1',avg:28,max:74,fvr:67,repeat:32},{label:'Week 2',avg:24,max:65,fvr:71,repeat:27},{label:'Week 3',avg:22,max:58,fvr:76,repeat:23},{label:'Week 4',avg:18,max:48,fvr:81,repeat:18}]});
let state;try{state=JSON.parse(localStorage.getItem('herd-v1'))||initial()}catch{state=initial()}let view='student',tab='overview',deptFilter='All departments',selectedAdvisor='a1',lastSaved=Date.now();
function save(){lastSaved=Date.now();localStorage.setItem('herd-v1',JSON.stringify(state));notifyQueue()}
function queue(d){return state.tickets.filter(t=>t.status==='Waiting'&&(!d||t.dept===d)).sort((a,b)=>score(b)-score(a))}function score(t){return (Date.now()-t.created)/60000+(t.urgency==='High'?30:0)}function active(d){return state.staff.filter(s=>s.active&&s.role==='Advisor'&&(!d||s.dept===d))}function wait(d){return active(d).length?Math.ceil(queue(d).length/active(d).length)*state.departments.find(x=>x.name===d).minutes:null}function est(t){return active(t.dept).length?Math.floor(queue(t.dept).findIndex(x=>x.id===t.id)/active(t.dept).length)*state.departments.find(x=>x.name===t.dept).minutes:null}function waited(t){return Math.max(0,Math.floor((Date.now()-t.created)/60000))}function badge(s){return `<span class="pill ${s==='High'?'red':s==='Waiting'?'warning':s==='In Progress'?'blue':s==='Inactive'?'gray':''}">${esc(s)}</span>`}function button(label,action,cls=''){return `<button class="btn ${cls}" data-action="${action}">${label}</button>`}function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4300)}
function notify(msg,key){if(state.notifications.some(n=>n.key===key))return;state.notifications.unshift({msg,key,time:Date.now(),read:false});localStorage.setItem('herd-v1',JSON.stringify(state));if('Notification'in window&&Notification.permission==='granted')new Notification('The Herd Helpdesk',{body:msg});$('#unread').hidden=false}
function notifyQueue(){let t=state.tickets.find(t=>t.id===state.own);if(!t||t.alerts===false)return;if(t.status==='Waiting'&&queue(t.dept).findIndex(x=>x.id===t.id)<3)notify('You’re in the top 3 for '+t.dept+'. Please stay nearby.','near-'+t.id);if(t.status==='In Progress')notify('Your advisor is ready. Head to the '+t.dept+' desk.','called-'+t.id);if(t.status==='Resolved'||t.status==='Transferred')notify('Your visit is complete. Your case summary is ready in My visit.','done-'+t.id)}
function modal(title,html){$('#modal-body').innerHTML=`<div class="modal-heading"><h2>${title}</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></div>${html}`;$('#modal').showModal()}function heading(kicker,title,desc,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><div class="date-chip">${extra||new Date().toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric',timeZone:'America/New_York'})}</div></div>`}function stat(label,value,detail){return `<div class="card"><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-detail">${detail}</div></div>`}function tabs(items){return `<div class="tabs">${items.map(([id,label])=>`<button data-tab="${id}" class="${tab===id?'selected':''}">${label}</button>`).join('')}</div>`}
function render(){ $('#nav').innerHTML=navs.map(([id,icon,label])=>`<button data-view="${id}" class="${view===id?'active':''}"><span class="nav-icon">${icon}</span>${label}<span class="arrow">›</span></button>`).join('');$('#crumb').textContent=navs.find(x=>x[0]===view)[2];$('#main').innerHTML=({student,advisor,supervisor,admin,analytics}[view])();$('#clock').textContent='Updated '+new Date(lastSaved).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',timeZone:'America/New_York'})+' ET';$('#unread').hidden=!state.notifications.some(n=>!n.read)}
function student(){let html=heading('Student portal','Your next step starts here.','Get the help you need, without putting your day on hold.');html+=tabs([['overview','Service overview'],['visit','My visit'],['cases','Case lookup']]);if(tab==='cases')return html+lookup();if(tab==='visit')return html+myVisit();return html+`<section class="hero"><div><div class="eyebrow">WELCOME TO THE HERD</div><h2>Less time in line.<br>More time being a Bison.</h2><p>Check wait times, join a queue, and track your visit.<br>We’ll let you know when it’s your turn.</p></div><div class="hero-right"><div class="live-chip"><span class="live-dot"></span>LIVE AT THE HUB</div><strong>${queue().length}</strong><span>students in queue</span></div></section><div class="section-heading"><div><h2>How can we help?</h2><p>Choose a department to get started.</p></div><span class="live-text"><span class="status-dot"></span> Live wait estimates</span></div><div class="cards">${state.departments.map((d,i)=>`<article class="card department-card"><div class="card-top"><div class="dept-icon ${['green','','red'][i]}">${icons[i]}</div>${badge(d.open&&active(d.name).length?'Available':d.open?'No advisors':'Closed')}</div><h3>${d.name}</h3><p>${['Aid packages, scholarships & eligibility','Enrollment, records & registration','Student accounts, billing & payments'][i]}</p><div class="wait">${wait(d.name)??'—'}<small>min estimated wait</small></div><div class="mini-stats"><span>◷ <b>${queue(d.name).length}</b> in queue</span><span>♙ <b>${active(d.name).length}</b> advisors available</span></div><div class="hours">◷ &nbsp; ${esc(d.hours)} ET</div>${button('Join queue <span>↗</span>','join:'+i,'full')}</article>`).join('')}</div><div class="bottom-grid"><section class="card"><div class="card-title-row"><h2>A little less waiting. A lot more clarity.</h2><span class="subtle">HOW IT WORKS</span></div><div class="steps">${[['Check in','Tell us a little about what you need.'],['Keep your place','Follow your queue and get an alert.'],['Move forward','Meet your advisor and track next steps.']].map(([a,b],i)=>`<div class="step"><div class="step-number">0${i+1}</div><h4>${a}</h4><p>${b}</p></div>`).join('')}</div></section><section class="card lookup-card"><div class="eyebrow">ALREADY VISITED THE HUB?</div><h2 style="margin-top:10px">Pick up where you left off.</h2><p>Find your case status, session summary, and anything still on your to-do list.</p>${button('Look up a case <span>→</span>','lookup','secondary')}</section></div>`}
function join(i){let d=state.departments[i];if(state.own&&state.tickets.some(t=>t.id===state.own&&['Waiting','In Progress'].includes(t.status))){tab='visit';render();toast('You already have an active visit.');return}if(!d.open||!active(d.name).length){toast('This department is currently unavailable. Please check its operating hours.');return}modal('Check in · '+d.name,`<p>A few details now help your advisor get you moving sooner.</p><form id="intake"><input type="hidden" name="dept" value="${esc(d.name)}"><div class="form-grid"><label>Full name<input name="name" autocomplete="name" required maxlength="80" placeholder="Your full name"></label><label>Student ID<input name="studentId" required pattern="@?[0-9]{8}" title="Enter 8 digits, optionally starting with @" placeholder="@03123456"></label><label>Issue category<select name="category">${Object.keys(state.routing).filter(c=>state.routing[c]===d.name).map(c=>`<option>${esc(c)}</option>`).join('')||'<option>General assistance</option>'}</select></label><label>Contact email<input name="contact" type="email" required placeholder="you@bison.howard.edu"></label><label>Mobile number (optional)<input name="phone" type="tel" placeholder="(202) 555-0123"></label><label>Urgency<select name="urgency"><option>Normal</option><option>High</option></select></label><label class="span-2">What can we help with?<textarea name="summary" required maxlength="1000" placeholder="Share your question and any upcoming deadlines."></textarea></label><label class="span-2 inline-checkbox"><input name="repeat" type="checkbox"> I’ve visited the Hub about this issue before.</label><label class="span-2 inline-checkbox"><input name="alerts" type="checkbox" checked> Enable simulated queue alerts. No real SMS will be sent.</label></div><div class="notice">Estimated wait: ${wait(d.name)} minutes · Your category determines the assigned department. Please use fictional details in this prototype.</div><div class="form-actions"><button class="btn teal" type="submit">Confirm check-in →</button><button type="button" class="btn secondary" data-action="close">Cancel</button></div></form>`)}
function myVisit(){let t=state.tickets.find(t=>t.id===state.own);if(!t)return `<div class="card empty"><div class="dept-icon" style="margin:0 auto 18px">◷</div><h2>Your day, with less waiting.</h2><p style="margin:12px">You haven’t checked in yet. Choose a department to join its queue.</p>${button('Explore departments','overview')}</div>`;let pos=queue(t.dept).findIndex(x=>x.id===t.id)+1,c=state.cases.filter(c=>c.studentId===t.studentId).at(-1);return `<div class="detail-grid"><div class="card"><div class="card-title-row"><h2>${t.status==='Waiting'?'You’re in the queue.':t.status==='In Progress'?'Your advisor is ready.':'Your visit is complete.'}</h2>${badge(t.status)}</div><div class="queue-big"><strong>${t.status==='Waiting'?pos:t.status==='In Progress'?'→':'✓'}</strong><h3>${t.status==='Waiting'?'your current position':t.status==='In Progress'?'Please head to the '+esc(t.dept)+' desk':'Thanks for stopping by'}</h3><p>${t.status==='Waiting'?Math.max(0,pos-1)+' people ahead · '+(est(t)??'—')+' minute estimated wait':esc(t.advisor||'Your case summary is below.')}</p></div><div class="progress-track"><div style="width:${t.status==='Waiting'?Math.max(10,100-pos*12):100}%"></div></div><div class="notice">${t.status==='Waiting'?'Your place updates automatically. We’ll alert you when you’re in the top 3. Estimates can change with staffing and urgent requests.':t.status==='In Progress'?'Your advisor has your intake details. You can refer to your ticket at the desk.':'Your advisor’s notes and pending actions will stay attached to your case.'}</div>${c?caseCard(c):''}</div><div><div class="card"><div class="eyebrow">YOUR VISIT</div><h2 style="margin-top:9px">${esc(t.id)}</h2>${[['Department',t.dept],['Issue',t.category],['Checked in',new Date(t.created).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})],['Contact',t.contact]].map(([a,b])=>`<div class="detail-line"><span>${a}</span><b>${esc(b)}</b></div>`).join('')}<p style="margin:15px 0">${esc(t.summary)}</p>${t.status==='Waiting'?button('Leave queue','leave','secondary full'):''}</div><div class="card" style="margin-top:18px"><h3>Stay in the loop</h3><p style="margin:10px 0">In-app alerts work automatically. Enable browser notifications to get updates while this page is open.</p>${button('Enable browser alerts','push','secondary')}</div></div></div>`}
function lookup(){return `<section class="card form-card"><div class="eyebrow">KEEP MOVING FORWARD</div><h2 style="margin-top:10px">Every visit has a next step.</h2><p style="margin-top:8px">Enter your case number to view your advisor’s notes and pending actions.</p><form id="case-search"><div class="form-grid"><label>Case number<input name="case" required placeholder="CASE-2026-0108"></label><label>Student ID<input name="student" required placeholder="@03196540"></label></div><button class="btn" type="submit">Find my case →</button></form><p style="margin-top:18px;font-size:10px">Try the sample: CASE-2026-0108 · @03196540</p><div id="case-result" aria-live="polite"></div></section>`}function caseCard(c){return `<div class="large-note"><div class="card-title-row"><h3>${esc(c.id)}</h3>${badge(c.status)}</div><p style="margin-top:9px">${esc(c.dept)} · Advisor ${esc(c.advisor)}</p><h4 style="margin:17px 0 6px">What we discussed</h4><p>${esc(c.summary)}</p><h4 style="margin:15px 0 6px">Next steps</h4><p>${esc(c.pending||'No pending actions. You’re all set.')}</p></div>`}
function advisor(){let a=state.staff.find(a=>a.id===selectedAdvisor);return heading('Advisor workspace','A clearer queue. A better conversation.','See the context, help the student, and keep the next step connected.')+`<div class="notice" style="margin-bottom:23px">Demo role preview · Queue access below follows the selected advisor’s active account and department. Production authentication is not connected.</div><div class="toolbar" style="margin-bottom:23px"><label for="advisor-select">Preview as</label><select id="advisor-select">${state.staff.map(s=>`<option value="${s.id}" ${a?.id===s.id?'selected':''}>${esc(s.name)} · ${esc(s.role)}${!s.active?' (Inactive)':''}</option>`).join('')}</select><span class="subtle">Priority = minutes waited + 30 for high urgency</span></div>`+(!a||!a.active||a.role!=='Advisor'?`<div class="card empty"><h2>Queue access restricted</h2><p style="margin-top:10px">An active advisor account is required to access student queue details.</p></div>`:`<div class="stats">${stat('Your department',a.dept,'Assigned service queue')}${stat('Waiting now',queue(a.dept).length,'Prioritized by urgency + wait')}${stat('Estimated wait',(wait(a.dept)??'—')+' min','Based on available advisors')}${stat('In progress',state.tickets.filter(t=>t.dept===a.dept&&t.status==='In Progress').length,'Active student sessions')}</div><section class="card"><div class="card-title-row"><h2>${esc(a.dept)} requests <span class="badge-num">${queue(a.dept).length}</span></h2><span class="live-text">● Live queue</span></div>${[...new Set(state.tickets.filter(t=>t.dept===a.dept&&['Waiting','In Progress'].includes(t.status)).map(t=>t.category))].map(category=>`<h3 style="margin-top:25px">${esc(category)}</h3>${ticketTable(state.tickets.filter(t=>t.dept===a.dept&&t.category===category&&t.status==='In Progress').concat(queue(a.dept).filter(t=>t.category===category)))}`).join('')||'<div class="empty"><p>No requests waiting. You’re all caught up.</p></div>'}</section>`)}
function ticketTable(tickets){return `<div class="table-wrap"><table><thead><tr><th>Student / ticket</th><th>Issue category</th><th>Wait</th><th>Priority</th><th>Status</th><th></th></tr></thead><tbody>${tickets.map(t=>`<tr><td><strong>${esc(t.name)}</strong><span class="subtle">${esc(t.id)}</span></td><td>${esc(t.category)}</td><td>${waited(t)} min</td><td>${badge(t.urgency)}</td><td>${badge(t.status)}</td><td>${button(t.status==='In Progress'?'Open session':'View request','ticket:'+t.id,'secondary')}</td></tr>`).join('')||'<tr><td colspan="6"><p class="empty">No requests waiting. You’re all caught up.</p></td></tr>'}</tbody></table></div>`}
function ticket(id){let a=state.staff.find(s=>s.id===selectedAdvisor),t=state.tickets.find(t=>t.id===id);if(view!=='advisor'||!a?.active||a.role!=='Advisor'||a.dept!==t?.dept){toast('Queue access restricted.');return}modal(t.status==='Waiting'?'Student request':'Active session',`<div class="card-title-row"><div><h2>${esc(t.name)}</h2><p>${esc(t.studentId)} · ${esc(t.id)}</p></div>${badge(t.urgency)}</div><div class="detail-line"><span>Issue</span><b>${esc(t.category)}</b></div><div class="detail-line"><span>Contact</span><b>${esc(t.contact)}</b></div><div class="large-note">${esc(t.summary)}</div><p style="margin-top:13px">${t.repeat?'Repeat visit reported.':'First visit reported.'} ${state.cases.filter(c=>c.studentId===t.studentId).length} prior cases on file.</p>${t.status==='Waiting'?`<div class="form-actions">${button('Call student →','call:'+t.id,'teal')}${button('Mark no-show','noshow:'+t.id,'secondary')}</div>`:`<form id="session"><input type="hidden" name="ticket" value="${t.id}"><div class="form-grid"><label class="span-2">Session summary<textarea name="summary" required placeholder="What was discussed and what was completed?"></textarea></label><label class="span-2">Pending actions<textarea name="pending" placeholder="Include any documents, next steps, or follow-up deadlines."></textarea></label><label>Outcome<select name="status"><option>Resolved</option><option>In Progress</option><option>Transferred</option></select></label><label>Transfer to<select name="transfer">${names.filter(d=>d!==t.dept).map(d=>`<option>${d}</option>`).join('')}</select></label></div><button class="btn teal" type="submit">Complete session & create case →</button></form>`}`)}
function supervisor(){return heading('Supervisor command center','Keep the whole Hub moving.','One view of demand, staffing, and the moments that need your attention.')+`<div class="stats">${stat('Students waiting',queue().length,'Across all three departments')}${stat('Average queue wait',Math.round(queue().reduce((s,t)=>s+waited(t),0)/(queue().length||1))+' min','Elapsed time of waiting students')}${stat('Active advisors',active().length,'Available across the Hub')}${stat('Sessions in progress',state.tickets.filter(t=>t.status==='In Progress').length,'Live service activity')}</div><div class="section-heading"><h2>Department capacity</h2><span class="live-text">● Live operations</span></div><div class="cards">${state.departments.map((d,i)=>`<div class="card"><div class="card-top"><div class="dept-icon">${icons[i]}</div>${badge((wait(d.name)||0)>20?'High demand':'Balanced')}</div><h2>${d.name}</h2><div class="wait" style="margin:18px 0;font-size:26px">${queue(d.name).length} <small>waiting · ${wait(d.name)??'—'} min estimate</small></div><p>${active(d.name).length} active advisors · ${state.staff.filter(s=>s.dept===d.name).length} assigned</p><div class="form-actions">${button('Reassign staff','reassign:'+i,'secondary')}${button('+ Request','request:'+i,'secondary')}</div></div>`).join('')}</div><div class="bottom-grid"><section class="card"><div class="card-title-row"><h2>Know the busy hours</h2><span class="subtle">SAMPLE · LAST 4 WEEKS</span></div><p style="margin-top:7px">Typical arrivals by day and hour. Plan coverage ahead.</p>${heatmap()}<div class="legend">Less ${[0,1,2,3,4].map(i=>`<i class="heat-cell level${i}"></i>`).join('')} More</div></section><section class="card"><h2>Staffing activity</h2>${state.requests.length?state.requests.slice(-5).reverse().map(r=>`<div class="activity"><div class="activity-icon">↔</div><div><strong>${esc(r.title)}</strong><p>${esc(r.detail)}</p></div></div>`).join(''):`<div class="activity"><div class="activity-icon">✓</div><div><strong>Coverage is up to date</strong><p>Advisor reassignments and staffing requests appear here.</p></div></div>`}<div class="notice" style="margin-top:20px">Staffing requests are recorded in this prototype. No external messages are sent.</div></section></div>`}
function heatmap(){let values=[[0,1,2,4,3,2,1,0],[1,2,3,4,3,2,2,1],[0,1,2,3,2,1,1,0],[1,2,3,3,2,2,1,0],[0,1,2,2,1,1,0,0]];return `<div class="heatmap"><span></span>${['9a','10a','11a','12p','1p','2p','3p','4p'].map(h=>`<span>${h}</span>`).join('')}${values.map((row,i)=>`<span>${['Mon','Tue','Wed','Thu','Fri'][i]}</span>${row.map((n,j)=>`<div class="heat-cell level${n}" title="${['Monday','Tuesday','Wednesday','Thursday','Friday'][i]}, ${j+9}:00: ${n*8+3} sample arrivals"></div>`).join('')}`).join('')}</div>`}
function admin(){let html=heading('System administration','Make the Hub work better.','Manage service hours, team access, and the rules behind every visit.')+tabs([['overview','Service settings'],['accounts','Staff accounts'],['routing','Routing rules'],['health','System health']]);if(tab==='accounts')return html+`<div class="card"><div class="card-title-row"><h2>Staff directory</h2>${button('+ Add account','add-account')}</div><p style="margin-top:8px">Active advisor accounts can preview their department’s queue. These are simulated roles.</p><div class="table-wrap"><table><thead><tr><th>Staff member</th><th>Role</th><th>Department</th><th>Status</th><th>Manage</th></tr></thead><tbody>${state.staff.map(s=>`<tr><td><strong>${esc(s.name)}</strong><span class="subtle">${s.id}</span></td><td>${esc(s.role)}</td><td>${esc(s.dept)}</td><td>${badge(s.active?'Active':'Inactive')}</td><td>${button('Edit','edit-account:'+s.id,'secondary')} ${button(s.active?'Deactivate':'Activate','toggle-account:'+s.id,'secondary')}</td></tr>`).join('')}</tbody></table></div></div>`;if(tab==='routing')return html+`<div class="card form-card"><h2>Issue-based routing</h2><p style="margin-top:8px">Every new check-in is assigned to the department configured below.</p><form id="routing"><div class="form-grid">${Object.entries(state.routing).map(([k,v])=>`<label>${esc(k)}<select name="${esc(k)}">${names.map(n=>`<option ${n===v?'selected':''}>${n}</option>`).join('')}</select></label>`).join('')}</div><button class="btn teal">Save routing rules →</button></form></div>`;if(tab==='health')return html+`<div class="stats">${stat('Prototype health',state.health?'Operational':'Simulated outage','Local status monitor')}${stat('Data persistence','Browser','This device only')}${stat('Refresh cadence','10 sec','Queue and time estimates')}${stat('Notifications',state.notifications.length,'Simulated event alerts')}</div><div class="card form-card"><h2>Health monitoring</h2><div class="notice" style="margin:20px 0">${state.health?'All prototype services are available.':'Simulated outage detected. An administrator alert has been generated.'} This is a health simulation, not production uptime telemetry.</div>${button(state.health?'Simulate outage':'Restore service','health','secondary')}<div class="large-note">Production requirements: connect authenticated staff identities, server-side access policies, durable shared storage, SMS delivery, and real service telemetry before using student records.</div></div>`;return html+`<section class="card form-card"><h2>Department operating hours</h2><p style="margin-top:8px">Changes appear immediately in the student service overview. Hours are Eastern Time.</p><form id="hours">${state.departments.map((d,i)=>`<div class="form-grid" style="border-bottom:1px solid var(--line);padding-bottom:20px"><label>${d.name}<input required name="hours${i}" value="${esc(d.hours)}" placeholder="9:00 AM – 5:00 PM"></label><label>Check-in availability<select name="open${i}"><option value="true" ${d.open?'selected':''}>Accepting check-ins</option><option value="false" ${!d.open?'selected':''}>Closed to check-ins</option></select></label></div>`).join('')}<button class="btn teal">Save service hours →</button></form><p style="margin-top:15px">Availability is manually controlled in this prototype; posted hours are informational.</p></section>`}
function account(id){let s=state.staff.find(s=>s.id===id)||{name:'',role:'Advisor',dept:'Financial Aid'};modal(id?'Edit staff account':'Add staff account',`<form id="account"><input name="id" type="hidden" value="${id||''}"><div class="form-grid"><label class="span-2">Full name<input name="name" required maxlength="80" value="${esc(s.name)}"></label><label>Role<select name="role">${['Advisor','Supervisor','Administrator'].map(r=>`<option ${s.role===r?'selected':''}>${r}</option>`).join('')}</select></label><label>Department<select name="dept">${names.map(n=>`<option ${s.dept===n?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="notice">This creates a prototype role record, not a real login account.</div><div class="form-actions"><button class="btn teal">Save account →</button></div></form>`)}
let reportDept='All departments',reportRange='4';function reportRows(){return state.history.slice(-Number(reportRange)).map((r,i)=>({...r,avg:r.avg+(reportDept==='Financial Aid'?5:reportDept==='Registrar'?-4:0),max:r.max+(reportDept==='Financial Aid'?9:reportDept==='Registrar'?-8:0)}))}
function analytics(){let rows=reportRows(),avg=Math.round(rows.reduce((s,r)=>s+r.avg,0)/rows.length),fvr=Math.round(rows.reduce((s,r)=>s+r.fvr,0)/rows.length);return heading('Service analytics','Turn service into insight.','Understand the wait, measure the outcome, and plan a better student experience.')+`<div class="toolbar" style="margin-bottom:24px"><select id="report-dept" aria-label="Report department">${['All departments',...names].map(n=>`<option ${reportDept===n?'selected':''}>${n}</option>`).join('')}</select><select id="report-range" aria-label="Report period"><option value="4" ${reportRange==='4'?'selected':''}>Last 4 sample weeks</option><option value="2" ${reportRange==='2'?'selected':''}>Last 2 sample weeks</option></select><span class="pill gray">Illustrative historical data</span><div style="margin-left:auto;display:flex;gap:8px">${button('↓ CSV','csv','secondary')}${button('↓ PDF','pdf','secondary')}</div></div><div class="stats">${stat('Average wait',avg+' min','Selected sample period')}${stat('Maximum wait',Math.max(...rows.map(r=>r.max))+' min','Longest recorded sample wait')}${stat('First-visit resolution',fvr+'%','Resolved in a single visit')}${stat('Repeat visits',rows.reduce((s,r)=>s+r.repeat,0),'Sample returning students')}</div><div class="bottom-grid" style="margin-top:0"><section class="card"><div class="card-title-row"><h2>Less time waiting</h2><span class="subtle">MINUTES BY WEEK</span></div><div class="chart">${rows.map(r=>`<div class="bar-group"><div class="bar" style="height:${r.avg}%" title="Average: ${r.avg} min"></div><div class="bar max" style="height:${r.max}%" title="Maximum: ${r.max} min"></div><small>${r.label}</small></div>`).join('')}</div><div class="legend"><i style="background:var(--teal)"></i> Average wait <i style="background:#c6d9dd;margin-left:12px"></i> Maximum wait</div></section><section class="card"><h2>Resolve it the first time</h2><p style="margin-top:8px">First-visit resolution trend</p>${rows.map(r=>`<div style="margin-top:19px"><div class="card-title-row"><span class="subtle">${r.label}</span><b style="font-size:11px">${r.fvr}%</b></div><div class="progress-track" style="margin:8px 0;height:7px"><div style="width:${r.fvr}%"></div></div></div>`).join('')}</section></div><section class="card" style="margin-top:22px"><div class="card-title-row"><h2>Repeat visits by issue</h2><span class="subtle">SELECTED SAMPLE PERIOD</span></div><div class="table-wrap"><table><thead><tr><th>Issue category</th><th>Department</th><th>Repeat visits</th><th>Opportunity</th></tr></thead><tbody>${[['Aid disbursement','Financial Aid',.45,'Clarify document requirements'],['Course registration','Registrar',.25,'Simplify registration guidance'],['Account hold','Bursar',.30,'Explain account hold next steps']].filter(r=>reportDept==='All departments'||r[1]===reportDept).map(r=>`<tr><td><strong>${r[0]}</strong></td><td>${r[1]}</td><td>${Math.round(rows.reduce((s,x)=>s+x.repeat,0)*r[2])}</td><td>${r[3]}</td></tr>`).join('')}</tbody></table></div></section><p style="margin-top:16px;font-size:10px">Historical charts use a labeled sample dataset. Current queue operations are available in the Supervisor hub.</p>`}
function download(name,content,type){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function pdf(){let lines=['THE HERD HELPDESK','Service analytics - illustrative sample data',reportDept+' | Last '+reportRange+' sample weeks','',...reportRows().map(r=>r.label+': average wait '+r.avg+' min | maximum '+r.max+' min | resolution '+r.fvr+'% | repeat '+r.repeat),'','Generated '+new Date().toISOString().slice(0,10),'Prototype data. Not an institutional service report.'];let stream='BT /F1 18 Tf 50 780 Td '+lines.map((s,i)=>(i?'0 -28 Td ':'')+'('+s.replace(/[()\\]/g,'\\$&')+') Tj').join('\n')+' ET';let objs=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>','<< /Length '+stream.length+' >>\nstream\n'+stream+'\nendstream'];let out='%PDF-1.4\n',offsets=[0];objs.forEach((o,i)=>{offsets.push(out.length);out+=(i+1)+' 0 obj\n'+o+'\nendobj\n'});let start=out.length;out+='xref\n0 6\n0000000000 65535 f \n'+offsets.slice(1).map(x=>String(x).padStart(10,'0')+' 00000 n \n').join('')+'trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n'+start+'\n%%EOF';download('herd-service-report.pdf',out,'application/pdf');toast('PDF report downloaded.')}
document.addEventListener('click',e=>{const n=e.target.closest('[data-view]');if(n){view=n.dataset.view;tab='overview';render();return}const tt=e.target.closest('[data-tab]');if(tt){tab=tt.dataset.tab;render();return}const el=e.target.closest('[data-action]');if(!el)return;const [action,id]=el.dataset.action.split(':');let t=state.tickets.find(t=>t.id===id);switch(action){case'close':$('#modal').close();break;case'join':join(Number(id));break;case'lookup':tab='cases';render();break;case'overview':tab='overview';render();break;case'ticket':ticket(id);break;case'leave':modal('Leave the queue?',`<p>Your current place will be released. You can check in again later.</p><div class="form-actions">${button('Leave queue','confirm-leave','danger')}${button('Keep my place','close','secondary')}</div>`);break;case'confirm-leave':{let own=state.tickets.find(t=>t.id===state.own);if(own)own.status='Cancelled';state.own=null;save();$('#modal').close();render();toast('You’ve left the queue.');break}case'push':if(!('Notification'in window)){toast('This browser does not support notifications. In-app alerts are still enabled.');break}Notification.requestPermission().then(p=>toast(p==='granted'?'Browser alerts enabled while this app is open.':'In-app alerts remain available in the notification center.'));break;case'call':{let a=state.staff.find(s=>s.id===selectedAdvisor);if(!t||!a?.active||a.role!=='Advisor'||a.dept!==t.dept)return;t.status='In Progress';t.advisor=a.name;t.waitMins=waited(t);save();render();ticket(id);toast('Student called. Queue position updated.');break}case'noshow':if(t){t.status='No-Show';save();$('#modal').close();render();toast('Marked as no-show.')}break;case'reassign':{let target=names[Number(id)];modal('Reassign an advisor',`<p>Move an active advisor to ${target}. Queue estimates adjust immediately.</p><div style="margin-top:20px">${active().filter(s=>s.dept!==target).map(s=>`<div class="detail-line"><div><b>${esc(s.name)}</b><p>${esc(s.dept)}</p></div>${button('Move here','move:'+s.id+':'+id,'secondary')}</div>`).join('')||'<p>No advisors available to move.</p>'}</div>`);break}case'move':{let target=names[Number(el.dataset.action.split(':')[2])],s=state.staff.find(s=>s.id===id);if(!s)return;let old=s.dept;s.dept=target;state.requests.push({title:s.name+' reassigned',detail:old+' → '+target});save();$('#modal').close();render();toast('Advisor reassigned to '+target+'.');break}case'request':{let target=names[Number(id)];state.requests.push({title:'Additional advisor requested',detail:target+' · Request recorded for supervisor review'});save();render();toast('Staffing request recorded for '+target+'.');break}case'add-account':account();break;case'edit-account':account(id);break;case'toggle-account':{let s=state.staff.find(s=>s.id===id);s.active=!s.active;save();render();toast(s.name+' is now '+(s.active?'active.':'inactive.'));break}case'health':state.health=!state.health;if(!state.health)notify('Administrator alert: simulated service outage detected.','outage-'+Date.now());save();render();toast(state.health?'Service restored.':'Outage simulation triggered an alert.');break;case'csv':{let rows=[['Department','Period','Average wait (min)','Maximum wait (min)','First-visit resolution (%)','Repeat visits'],...reportRows().map(r=>[reportDept,r.label,r.avg,r.max,r.fvr,r.repeat])];download('herd-service-report.csv',rows.map(r=>r.map(c=>'"'+String(c).replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv');toast('CSV report downloaded.');break}case'pdf':pdf();break;case'reset':localStorage.removeItem('herd-v1');state=initial();save();$('#modal').close();render();toast('Sample data restored.');break;case'coverage':modal('Requirements coverage',`<p>The prototype maps to all eight feature groups. Production integrations remain necessary for real student use.</p><div class="audit-list">${[['F1 · R1–R4','Live queue & staffing'],['F2 · R6','Check-in & intake'],['F3 · R5','Simulated push / SMS alerts'],['F4 · R7–R10','Priority advisor workspace'],['F5 · R11–R13','Cases, summaries & lookup'],['F6 · R14–R17','Capacity & staff reassignment'],['F7 · R18–R22','Hours, simulated RBAC & health'],['F8 · R23–R26','Sample analytics & PDF / CSV']].map(([a,b])=>`<div><b>${a}</b><p>${b}</p></div>`).join('')}</div>`);break}});
document.addEventListener('submit',e=>{if(!['intake','case-search','session','hours','routing','account'].includes(e.target.id))return;e.preventDefault();let f=Object.fromEntries(new FormData(e.target));switch(e.target.id){case'intake':{let dept=state.routing[f.category]||f.dept;if(!state.departments.find(d=>d.name===dept)?.open||!active(dept).length){toast('The routed department is unavailable. Please try later.');return}let id='HH-'+String(Date.now()).slice(-7);state.tickets.push({id,name:f.name.trim(),studentId:f.studentId.startsWith('@')?f.studentId:'@'+f.studentId,contact:f.contact,phone:f.phone,dept,category:f.category,summary:f.summary.trim(),urgency:f.urgency,repeat:!!f.repeat,alerts:!!f.alerts,created:Date.now(),status:'Waiting'});state.own=id;save();$('#modal').close();tab='visit';render();toast('You’re checked in. Ticket '+id+' is ready.');break}case'case-search':{let student=f.student.startsWith('@')?f.student:'@'+f.student;let c=state.cases.find(c=>c.id===f.case.trim().toUpperCase()&&c.studentId===student.trim());$('#case-result').innerHTML=c?caseCard(c):'<div class="notice" style="margin-top:20px">We couldn’t find that case and student ID combination. Check both values and try again.</div>';break}case'session':{let t=state.tickets.find(t=>t.id===f.ticket),a=state.staff.find(s=>s.id===selectedAdvisor);if(!t||!a?.active||a.dept!==t.dept||t.status!=='In Progress'){toast('This session is no longer available.');return}let c={id:'CASE-2026-'+String(Date.now()).slice(-7),ticketId:t.id,studentId:t.studentId,name:t.name,advisor:a.name,dept:t.dept,summary:f.summary.trim(),pending:f.pending.trim(),status:f.status==='Resolved'?'Resolved':'In Progress',created:Date.now()};state.cases.push(c);t.status=f.status==='In Progress'?'Follow-up':f.status;t.caseId=c.id;if(f.status==='Transferred'){let next={...t,id:'HH-'+String(Date.now()).slice(-7),dept:f.transfer,status:'Waiting',created:Date.now(),summary:'Transferred from '+t.dept+': '+f.summary,repeat:true};state.tickets.push(next);if(state.own===t.id)state.own=next.id;notify('Your session summary is ready: '+c.id+'. You’ve been transferred to '+f.transfer+'.','transfer-'+t.id)}else notify('Your case '+c.id+' is ready. Status: '+c.status+'.','case-'+t.id);save();$('#modal').close();render();modal('Case created',`<p>The session summary and next steps are ready for the student.</p>${caseCard(c)}<div class="form-actions">${button('Done','close','teal')}</div>`);break}case'hours':state.departments.forEach((d,i)=>{d.hours=f['hours'+i].trim();d.open=f['open'+i]==='true'});save();render();toast('Operating hours updated in the student portal.');break;case'routing':state.routing=f;save();toast('Routing rules saved. New check-ins will use these assignments.');break;case'account':{let s=state.staff.find(s=>s.id===f.id);if(s)Object.assign(s,{name:f.name.trim(),role:f.role,dept:f.dept});else state.staff.push({id:'a'+Date.now(),name:f.name.trim(),role:f.role,dept:f.dept,active:true});save();$('#modal').close();render();toast('Staff account saved.');break}}});
document.addEventListener('change',e=>{if(e.target.id==='advisor-select'){selectedAdvisor=e.target.value;render()}if(e.target.id==='report-dept'){reportDept=e.target.value;render()}if(e.target.id==='report-range'){reportRange=e.target.value;render()}});
$('#bell').onclick=()=>{modal('Your notifications',`<p>Queue and case updates · Simulated delivery</p><div style="margin-top:16px">${state.notifications.length?state.notifications.map(n=>`<div class="activity"><div class="activity-icon">↗</div><div><strong>${esc(n.msg)}</strong><p>${new Date(n.time).toLocaleString()}</p></div></div>`).join(''):'<div class="empty"><h3>You’re all caught up.</h3><p>Queue and case updates will appear here.</p></div>'}</div>`);state.notifications.forEach(n=>n.read=true);save();$('#unread').hidden=true};
$('#about').onclick=()=>modal('Built for the Bison journey',`<p>The Herd Helpdesk is an interactive prototype based on Howard University’s requirements traceability matrix (R1–R26, F1–F8).</p><div class="large-note">Use the sidebar to explore all five roles. Check in as a student, call the ticket from its advisor queue, then complete the session to generate a case.<br><br>Use fictional information. Records are saved only in this browser. Role switching is for demonstration and is not secure authentication. Queue updates use a 10-second local refresh and browser-tab sync, not WebSockets. SMS and health alerts are simulated. Historical charts use sample data.</div><div class="form-actions">${button('View requirements map','coverage','secondary')}${button('Reset sample data','reset','secondary')}</div>`);
window.addEventListener('storage',e=>{if(e.key==='herd-v1'&&e.newValue){state=JSON.parse(e.newValue);notifyQueue();render()}});setInterval(()=>{notifyQueue();if(!$('#modal').open&&!(view==='student'&&tab==='cases')&&!(view==='admin'&&['overview','routing'].includes(tab)))render()},10000);render();
